/** Two reordered outer parameters and all-value counter-relations survive real settlement and reopen. */
final class ContextTwoOuterExistential {
    static int checks;static final int WORK=64000000;
    static void require(boolean value,String why){++checks;if(!value)throw new AssertionError(why);}
    static void verdict(ContextUniversalCandidate.Evaluation e,boolean leading,boolean negative,boolean candidateRule,int mode,String rule,String candidate,String fact,String deny){
        boolean safe=mode!=1;require(e.status==(safe?Status.CONSISTENT:Status.COLLISION),"outer parameter family verdict: "+e.status+" / "+e.reason);
        if(safe){ContextUniversalFamilyModel.Certificate cert=e.qualification.certificate;require(cert!=null&&e.qualification.collision==null&&cert.cuts.size()==4,"all four cuts modeled");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut c:cert.cuts){require(c.receipt.verified&&c.receipt.input==cert.input&&c.model.ledger==c.receipt.closureStep.input,"exact model/closure/common-frontier binding");receipts.add(c.receipt);models.add(c.model);}require(ContextUniversalFamilyModel.certify(cert.input,receipts,models,16,65536,WORK).certified,"independent all-admissible-value model recertification");if(candidateRule)counter(e,leading,negative,rule,deny);}
        else collision(e.qualification,e.artifact.foreign,e.artifact.staged,candidateRule,rule,candidate,fact,deny);
    }
    static void counter(ContextUniversalCandidate.Evaluation e,boolean leading,boolean negative,String rule,String deny){
        Entry local=e.artifact.staged.primary.stream().filter(v->v.statement.equals(rule)).findFirst().get(),opposite=e.artifact.foreign.stream().flatMap(v->v.primary.stream()).filter(v->v.statement.equals(deny)).findFirst().get();Atom head=opposite.clauses.get(0).literals.get(0);SemanticTermSnapshot valueV=head.arguments.get(0).value,valueU=head.arguments.get(1).value;Set<Source> support=new HashSet<>(Arrays.asList(local.source,opposite.source));int u=leading?2:0,v=leading?1:2,x=leading?0:1;
        require(e.qualification.certificate.input.products.stream().anyMatch(row->{if(row.clause.literals.size()!=1||row.clause.variables.size()!=1||!row.support.sources.equals(support))return false;Atom a=row.clause.literals.get(0);return a.predicate.equals("rel")&&a.positive==negative&&a.arguments.size()==3&&a.arguments.get(u).variable<0&&a.arguments.get(u).value.semanticallyEquals(valueU)&&a.arguments.get(v).variable<0&&a.arguments.get(v).value.semanticallyEquals(valueV)&&a.arguments.get(x).variable>=0;}),"counter-relation fixes both denied outer parameters in inverse head order, inner stays universal with exact whole rule+Deny support");
    }
    static void collision(ContextUniversalFamilyInspection.Result r,List<Snapshot> foreign,Snapshot staged,boolean candidateRule,String rule,String candidate,String fact,String deny){
        require(r.status==Status.COLLISION&&r.certificate==null&&r.collision!=null&&!r.collision.oppositions.isEmpty(),"complete actual reordered-head contradiction");Set<Source> expectedForeign=new HashSet<>();for(Snapshot f:foreign)for(Entry e:f.primary)if(e.statement.equals(deny)||(!candidateRule&&e.statement.equals(rule)))expectedForeign.add(e.source);require(expectedForeign.size()==(candidateRule?1:2),"exact whole private rule/Deny Sources");Set<Source> expectedLocal=new HashSet<>();if(staged!=null)for(Entry e:staged.primary)if(e.statement.equals(candidate)||(candidateRule&&e.statement.equals(fact)))expectedLocal.add(e.source);
        for(ContextUniversalUnitProof.Proof p:r.collision.oppositions){Set<Source> local=new HashSet<>(),other=new HashSet<>();for(Source s:p.support.sources)(s.localX?local:other).add(s);require(p.dependsOnX&&p.contradiction&&p.conclusion==null&&p.support.sources.size()==3&&local.size()==(candidateRule?2:1)&&other.equals(expectedForeign),"only necessary three whole Sources; no base/marker import");if(staged!=null)require(local.equals(expectedLocal),"exact proposed and producer source identities");}
    }
    static void one(boolean leading,boolean negative,boolean reverse,boolean nativePath,boolean candidateRule,int mode)throws Exception{
        Path dir=Files.createTempDirectory("two-outer-existential-write-");System.setProperty("user.home",dir.toString());String s=negative?"~":"",op=negative?"":"~",rule="!@u @v ($x "+s+"rel("+(leading?"x,v,u":"u,x,v")+"))->"+s+"out(v,u);",fact="!"+s+"rel("+(leading?"9,2,1":"1,9,2")+");",pair=mode==2?"1,2":mode==3?"9,1":mode==4?"2,9":"2,1",deny="!"+op+"out("+pair+");",candidate=candidateRule?rule:mode==0?"!safe(1);":fact;boolean safe=mode!=1;
        ContextSevenPremiseNativeWriteRunner.create(dir,"Bridge",candidateRule?"!bridgeMarker(2);":rule);ContextSevenPremiseNativeWriteRunner.create(dir,"Deny",deny);ContextSevenPremiseNativeWriteRunner.create(dir,"Other","!other(2);");Set<String> settled;List<RevisionRef> pins;long afterRevision;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){
            require(f.root.compile("!base(2);"+(candidateRule&&mode!=0?" "+fact:""),null,false),"only selected original relation fact");for(String name:reverse?new String[]{"Other","Deny","Bridge"}:new String[]{"Bridge","Deny","Other"})f.db.connectContext(name);f.db.saveConnections(f.root);
            ContextProductionInventory before=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> origins=ContextSevenPremiseNativeWriteRunner.origins(before);long revision=f.db.getRevision();int rules=f.root.getRules().size();pins=ContextSevenPremiseNativeWriteRunner.pins(f);List<String> foreignPrints;
            try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){foreignPrints=ContextForeignAntecedentQuantifier.fingerprints(lease.inventory());require(lease.bind(WORK,500000).foreign.size()==3,"every private cut bound");}
            ContextUniversalCandidate.Evaluation diagnostic=f.db.qualifyUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK);verdict(diagnostic,leading,negative,candidateRule,mode,rule,candidate,fact,deny);require(f.db.getRevision()==revision&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(before.fingerprint),"diagnostic preserves exact physical source");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(candidate,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(safe)require(failure==null,"actual native two-outer-parameter safe publication");else{require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified&&failure.getFamilyAudit().verdict!=diagnostic.qualification,"actual native reordered-head conflict freshly audited");collision(failure.getFamilyAudit().verdict,diagnostic.artifact.foreign,null,candidateRule,rule,candidate,fact,deny);}}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,candidate,1000,16,16,16,65536,1000000,WORK,500000,WORK,WORK,false);require(result.status==(safe?DB.ProductionWriteStatus.PUBLISHED:DB.ProductionWriteStatus.COLLISION)&&result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"fresh exact public trial/audit governs two-outer-parameter verdict");verdict(result.trial,leading,negative,candidateRule,mode,rule,candidate,fact,deny);require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"actual public physical references");}
            ContextProductionInventory after=ContextSevenPremiseNativeWriteRunner.inventory(f);settled=ContextSevenPremiseNativeWriteRunner.origins(after);afterRevision=f.db.getRevision();Set<String> expected=new HashSet<>(origins);if(safe)expected.add(candidate);require(settled.equals(expected)&&after.primary.size()==expected.size()&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"only whole proposed Source publishes; no foreign/derived primary import");if(safe)require(afterRevision>revision,"safe publication advances physical revision");else require(afterRevision==revision&&f.root.getRules().size()==rules&&after.fingerprint.equals(before.fingerprint),"conflict preserves exact revision/rules/fingerprint");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(ContextForeignAntecedentQuantifier.fingerprints(lease.inventory()).equals(foreignPrints),"all initialized foreign inventories unchanged");}
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,"X")){require(f.db.getRevision()>=afterRevision&&ContextSevenPremiseNativeWriteRunner.origins(ContextSevenPremiseNativeWriteRunner.inventory(f)).equals(settled)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"ordinary durable reopen retains exact settled whole origins and pins");try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(f.db,f.root,1000)){require(lease.bind(WORK,500000).foreign.size()==3,"all private cuts bind after reopen");}}
    }
    static void run(boolean leading,boolean negative,String marker){try{for(boolean r:new boolean[]{false,true})for(boolean p:new boolean[]{false,true})for(boolean c:new boolean[]{false,true})for(int m=0;m<5;m++)one(leading,negative,r,p,c,m);System.out.println(marker+" checks="+(checks+ContextSevenPremiseNativeWriteRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
